<?php get_header(); $t = mgt_copy(); $site = mgt_contacts(); $slides = mgt_slides(); ?>
<main id="main"><h1 class="sr-only"><?php echo esc_html($t['footerCompany']); ?></h1>
<?php /* Previous opening hero intentionally retained only in the original Next.js source. */ ?>
<?php if ($slides): ?>
<section id="products" class="slider" aria-roledescription="carousel" aria-label="<?php echo esc_attr($t['nav'][1]); ?>" tabindex="0">
<div class="slides-track"><?php foreach ($slides as $index=>$slide): ?>
<article class="slide<?php echo $index === 0 ? ' is-active' : ''; ?>" aria-hidden="<?php echo $index === 0 ? 'false':'true'; ?>"><img src="<?php echo esc_url($slide['image']); ?>" alt="" <?php echo $index === 0 ? 'fetchpriority="high"' : 'loading="lazy"'; ?>><div class="slide-shade"></div><div class="shell slide-content" dir="<?php echo mgt_en()?'ltr':'rtl'; ?>"><span><?php echo esc_html(sprintf('%02d',$index+1)); ?></span><h2><?php echo esc_html($slide['title']); ?></h2><p><?php echo esc_html($slide['caption']); ?></p><?php if ($slide['href']): ?><a class="slide-link" href="<?php echo esc_url($slide['href']); ?>" tabindex="<?php echo $index === 0?'0':'-1'; ?>"><?php echo esc_html(mgt_text('مشاهده محصولات','Explore products')); ?> <span aria-hidden="true"><?php echo mgt_en()?'→':'←'; ?></span></a><?php endif; ?></div></article>
<?php endforeach; ?></div>
<?php if (count($slides)>1): ?>
<button class="slider-arrow slider-prev" type="button" aria-label="<?php echo esc_attr($t['previousSlide']); ?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 6-6 6 6 6"/></svg></button><button class="slider-arrow slider-next" type="button" aria-label="<?php echo esc_attr($t['nextSlide']); ?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></button>
<button class="slider-pause" type="button" aria-label="<?php echo esc_attr(mgt_text('توقف اسلایدر','Pause slideshow')); ?>">Ⅱ</button>
<?php endif; ?>
<span class="slide-counter" dir="ltr" aria-hidden="true"><b style="font-weight:400" data-slide-current>01</b> <span>/ <?php echo esc_html(sprintf('%02d',count($slides))); ?></span></span>
<div class="slider-dots"><?php foreach ($slides as $index=>$slide): ?><button class="<?php echo $index===0?'active':''; ?>" data-slide="<?php echo esc_attr($index); ?>" type="button" aria-label="<?php echo esc_attr($t['goToSlide'] . ' ' . ($index+1)); ?>" aria-current="<?php echo $index===0?'true':'false'; ?>"></button><?php endforeach; ?></div>
</section>
<div class="category-strip" aria-label="<?php echo esc_attr($t['nav'][1]); ?>"><?php foreach ($slides as $index=>$slide): ?><button type="button" data-slide="<?php echo esc_attr($index); ?>" class="<?php echo $index===0?'selected':''; ?>" aria-pressed="<?php echo $index===0?'true':'false'; ?>"><span aria-hidden="true"><?php echo esc_html(sprintf('%02d',$index+1)); ?></span><?php echo esc_html($slide['title']); ?><span class="category-arrow" aria-hidden="true"><?php echo mgt_en()?'↗':'↖'; ?></span></button><?php endforeach; ?></div>
<?php endif; ?>
<section id="about" class="about section-pad"><div class="shell about-grid"><div class="section-title"><span class="section-kicker"><span>01</span> <?php echo esc_html($t['aboutLabel']); ?></span><h2 class="multiline"><?php echo esc_html($t['aboutTitle']); ?></h2></div><div class="about-copy"><p class="lead"><?php echo esc_html($t['belief']); ?></p><div class="director-message"><span class="director-label"><?php echo esc_html($t['directorLabel']); ?></span><blockquote><?php echo esc_html($t['directorMessage']); ?></blockquote></div></div></div></section>
<section id="contact" class="contact section-pad"><div class="shell"><div class="contact-heading"><div><span class="section-kicker"><span>02</span> <?php echo esc_html($t['contactLabel']); ?></span><p><?php echo esc_html($t['contactText']); ?></p></div></div><div class="contact-groups">
<?php $contacts = [
    [['label'=>$t['addressLabel'],'value'=>$t['address'],'wide'=>true],['label'=>$t['officePhone'],'value'=>$site['officePhone'],'href'=>'tel:'.$site['officePhone']],['label'=>$t['companyEmail'],'value'=>$site['companyEmail'],'href'=>'mailto:'.$site['companyEmail']]],
    [['label'=>$t['managementPhone'],'value'=>$site['managementPhone'],'href'=>'tel:'.$site['managementPhone']],['label'=>$t['directorEmail'],'value'=>$site['directorEmail'],'href'=>'mailto:'.$site['directorEmail']]],
]; foreach ($contacts as $i=>$group): ?>
<div class="contact-group"><h2><span class="contact-dot"></span><?php echo esc_html($i===0?$t['companyGroup']:$t['managementGroup']); ?></h2>
<?php foreach ($group as $item): ?><div class="contact-row<?php echo !empty($item['wide'])?' address-row':''; ?>"><span class="contact-card-label"><?php echo esc_html($item['label']); ?></span><div class="contact-details"><?php if (isset($item['href'])): ?><a class="contact-value" href="<?php echo esc_url($item['href']); ?>" dir="ltr"><?php echo esc_html($item['value']); ?></a><?php else: ?><p class="contact-value"><?php echo esc_html($item['value']); ?></p><?php endif; ?><button class="copy-button" type="button" data-copy="<?php echo esc_attr($item['value']); ?>" aria-label="<?php echo esc_attr($t['copy'].' '.$item['label']); ?>" title="<?php echo esc_attr($t['copy']); ?>"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="11" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/></svg></button></div></div><?php endforeach; ?>
</div><?php endforeach; ?></div><span class="copy-notice" role="status"></span></div></section>
</main><?php get_footer(); ?>
